/* Dependency-free DOM MODEL checks only, not browser/visual acceptance. */
'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm'),path=require('node:path');
const base=fs.readFileSync(path.join(__dirname,'workspace_ui_dom_check.js'),'utf8');
const model={require,__dirname,console,setImmediate,URL,URLSearchParams};vm.createContext(model);
vm.runInContext(base.slice(0,base.indexOf('const tests=[];'))+'\nglobalThis.makeHarness=harness;globalThis.flush=tick;',model);
const {makeHarness,flush:tick}=model;
const clone=x=>JSON.parse(JSON.stringify(x));
const member={selector:'garden',context:'g'.repeat(64)};
const group=()=>({group_id:'group-fictional',label:'Fictional group',revision:1,members:[clone(member)],stopped:false,stop_review:null});
function harness(options={}) {
 const groups=options.groups||[];let h;
 h=makeHarness({...options,get:(url,r,d)=>url==='/api/relationships'?r(groups):options.get?options.get(url,r,d):null,post:(body,r)=>{
  if(options.post)return options.post(body,r,h);
  if(body.operation){const g=groups.find(g=>g.group_id===body.group_id);return r({...body.operation==='create'?{operation:'create',registry_revision:0,...body.spec,revision:1}:{operation:body.operation,group_id:g.group_id,revision:g.revision,members:g.members,...body.member?{member:body.member}:{}},review_digest:'d'.repeat(64)});}
  const review=body.review;
  if(review){let g=groups.find(g=>g.group_id===review.group_id);if(g&&review.revision!==g.revision)return r({error:'Relationship review changed; review exact membership again'},false);
   if(review.operation==='create'){g={group_id:review.group_id,label:review.label,revision:review.revision,members:clone(review.members),stopped:false,stop_review:null};groups.push(g);}else if(review.operation==='attach'){g.members.push(review.member);g.revision++;}else{g.stopped=true;g.revision++;g.stop_review=clone(review);}return r(g);}
  return r({kind:'request',card:h.card});
 }});
 h.groups=groups;h.field=id=>h.nodes.findLast(n=>n.id===id);
 h.form=async()=>{await tick();await h.view('relationships');h.field('groupId').value='group-fictional';h.field('groupLabel').value='Fictional group';h.field('groupMember-garden').checked=true;};
 h.preview=async()=>{await h.form();await h.find('Preview exact group').click();};return h;
}
const tests=[];const test=(n,f)=>tests.push([n,f]);
test('group navigation and pure preview grant nothing',async()=>{const h=harness();await h.preview();assert.equal(h.groups.length,0);assert.deepEqual(clone(h.posts[0]),{operation:'create',spec:{group_id:'group-fictional',label:'Fictional group',members:[member]}});assert.match(h.ids.content.textContent,/No immediate preemption/);assert.match(h.ids.content.textContent,/registry_revision/);});
test('exact phrase and group scope without undefined owner',async()=>{const h=harness();await h.preview();await h.find('Confirm reviewed group create').click();assert(!h.ids.dialogBody.textContent.includes('undefined'));assert.match(h.ids.dialogBody.textContent,/group-fictional/);assert.match(h.ids.dialogBody.textContent,/gggggg/);await h.confirm('create group');assert.equal(h.posts.length,1);await h.confirm('CREATE GROUP');assert.equal(h.posts.length,2);assert.equal(h.posts[1].review.review_digest,'d'.repeat(64));assert.equal(h.posts[1].review.registry_revision,0);assert.equal(h.groups.length,1);});
test('detached edited membership cannot change frozen review or re-preview',async()=>{const h=harness();await h.form();const old=h.find('Preview exact group'),label=h.field('groupLabel'),choice=h.field('groupMember-astronomy');await old.click();label.value='changed';choice.checked=true;await old.click();assert.equal(h.posts.length,1);await h.find('Confirm reviewed group create').click();await h.confirm('CREATE GROUP');assert.deepEqual(clone(h.posts[1].review.members),[member]);assert.equal(h.posts[1].review.label,'Fictional group');});
test('discard returns to new empty review form',async()=>{const h=harness();await h.preview();await h.find('Discard review and inspect groups').click();assert(h.find('Preview exact group'));assert(!h.find('Confirm reviewed group create'));assert.equal(h.posts.length,1);});
test('preview keeps catalog navigation usable',async()=>{const h=harness();await h.preview();await h.find('garden · open').click();assert.equal(h.context.location.hash,'#garden/alice/inbox');assert.equal(h.posts.length,1);});
test('attach requires fresh full membership review',async()=>{const h=harness({groups:[group()]});await tick();await h.view('relationships/group-fictional');await h.find('Review attach astronomy').click();await h.find('Confirm reviewed group attach').click();await h.confirm('ATTACH TASK');assert.equal(h.groups[0].revision,2);assert.deepEqual(clone(h.posts[1].review.members),[member]);assert.equal(h.posts[1].review.member.selector,'astronomy');});
test('membership revision change rejected without retry',async()=>{const h=harness({groups:[group()]});await tick();await h.view('relationships/group-fictional');await h.find('Review stop further group work').click();h.groups[0].revision++;h.groups[0].members.push({selector:'astronomy',context:'a'.repeat(64)});await h.find('Confirm reviewed group stop').click();await h.confirm('STOP GROUP');assert.equal(h.groups[0].stopped,false);assert.match(h.ids.error.textContent,/review changed/);assert(h.find('Confirm reviewed group stop').disabled);assert.equal(h.posts.length,2);});
test('stop commits exact review and has no resume or attach',async()=>{const h=harness({groups:[group()]});await tick();await h.view('relationships/group-fictional');await h.find('Review stop further group work').click();await h.find('Confirm reviewed group stop').click();await h.confirm('STOP GROUP');assert(h.groups[0].stopped);assert.deepEqual(clone(h.posts[1].review.members),[member]);assert(!h.find('Review stop further group work'));assert(!h.find('Review attach astronomy'));assert(h.find('Inspect task garden'));});
test('saved confirmation and raw hash navigation fence stale commit',async()=>{const h=harness();await h.preview();await h.find('Confirm reviewed group create').click();const saved=h.ids.dialogConfirm.onclick;await h.view('garden/alice/inbox');h.ids.confirmation.value='CREATE GROUP';saved();await tick();assert.equal(h.posts.length,1);await h.preview();await h.find('Confirm reviewed group create').click();h.context.location.hash='#astronomy/bob/inbox';await h.confirm('CREATE GROUP');assert.equal(h.posts.length,2);});
test('delayed preview cannot overwrite another task',async()=>{let release;const h=harness({post:()=>new Promise(r=>release=r)});await h.form();await h.find('Preview exact group').click();await h.view('garden/alice/inbox');release(h.response({operation:'create',group_id:'group-fictional',members:[member]}));await tick();assert(!h.find('Confirm reviewed group create'));assert.match(h.ids.content.textContent,/garden-task/);});
test('duplicate commit clicks and lost reply never retry',async()=>{const h=harness({post:(body,r)=>body.operation?r({operation:'create',registry_revision:0,group_id:body.spec.group_id,label:body.spec.label,revision:1,members:body.spec.members,review_digest:'d'.repeat(64)}):Promise.reject(Error('lost'))});await h.preview();const commit=h.find('Confirm reviewed group create');await commit.click();h.ids.confirmation.value='CREATE GROUP';h.ids.confirmation.oninput();const saved=h.ids.dialogConfirm.onclick;saved();saved();await tick();await commit.click();assert.equal(h.posts.length,2);assert.match(h.ids.error.textContent,/Inspect this exact group/);assert.match(h.ids.error.textContent,/may have committed/);assert(commit.disabled);assert(h.find('Inspect group without retry'));});
test('malicious labels remain inert text',async()=>{const h=harness();await h.form();h.field('groupLabel').value='<img src=x onerror=evil()> https://evil.invalid';await h.find('Preview exact group').click();assert.match(h.ids.content.textContent,/<img/);assert(!h.nodes.some(n=>['IMG','A','SCRIPT','IFRAME'].includes(n.tagName)));});
test('overlapping stop fences not-created tasks without global disabling',async()=>{const g=group(),stopped={...group(),group_id:'group-stopped',revision:2,stopped:true,stop_review:{operation:'stop',group_id:'group-stopped',revision:1,members:[member],review_digest:'d'.repeat(64)}};const h=harness({phase:'not_created',groups:[g,stopped]});await tick();h.rows[0].local_work_stopped=true;h.rows[0].relationship_groups=[g,stopped];await h.view('garden/alice/inbox');assert(!h.find('Create selected temporary task'));assert.match(h.ids.content.textContent,/group-stopped/);await h.view('astronomy/bob/inbox');assert(h.find('Create selected temporary task'));await h.view('relationships/group-fictional');assert(!h.find('Review attach astronomy'));assert(h.find('Review stop further group work'));});
test('stopped task history keeps decline/defer but no new authority',async()=>{const h=harness();await tick();h.rows[0].local_work_stopped=true;h.card.can_replace=true;h.card.can_prepare_fresh=true;await h.view('garden/alice/request/'+h.card.request_id);assert(!h.find('Approve exact request'));assert(!h.find('Prepare new review'));assert(!h.find('Prepare fresh unsigned review'));assert(h.find('Decline'));assert(h.find('Defer'));assert(h.find('Prepare next review').disabled);assert(h.find('Close only this task'));await h.find('Decline').click();assert.equal(h.posts[0].request.action,'decline');});
test('stopped delivery disables attempt and process but retains receipt checking',async()=>{const h=harness();await tick();h.rows[0].local_work_stopped=true;h.status.can_process=true;await h.view('garden/alice/delivery/'+h.card.request_id);assert(h.find('Retry approved delivery').disabled);assert(h.find('Process received message').disabled);assert(!h.find('Check existing receipt').disabled);});
test('local action gate blocks forbidden direct sends and previews',async()=>{const h=harness();await tick();h.rows[0].local_work_stopped=true;await h.view('garden/alice/inbox');for(const action of ['bind','create','next','approve','submit','attempt','process','import','prepare_response','cancel','revoke'])await vm.runInContext(`mutate(active,{action:${JSON.stringify(action)}})`,h.context);await vm.runInContext("post(active,'/api/response-preview',{},true)",h.context);assert.equal(h.posts.length,0);assert.match(h.ids.error.textContent,/stop prevents/);});
test('state-level stop supersedes catalog and blocks direct composition',async()=>{const h=harness({get:(url,r,d)=>url.startsWith('/api/state')?Promise.resolve(d(url)).then(async v=>r({...await v.json(),local_work_stopped:true})):null});await tick();await h.view('garden/alice/response');assert(!h.find('Preview exact response'));assert.match(h.ids.content.textContent,/Further local work stopped/);assert(h.find('Prepare next review').disabled);});
test('delayed commit cannot redirect a later task view',async()=>{let release;const h=harness({post:(body,r)=>body.operation?r({operation:'create',registry_revision:0,group_id:body.spec.group_id,label:body.spec.label,revision:1,members:body.spec.members,review_digest:'d'.repeat(64)}):new Promise(resolve=>release=resolve)});await h.preview();await h.find('Confirm reviewed group create').click();await h.confirm('CREATE GROUP');await h.view('astronomy/bob/inbox');release(h.response(group()));await tick();assert.equal(h.context.location.hash,'#astronomy/bob/inbox');assert.match(h.ids.content.textContent,/astronomy-task/);assert.equal(h.posts.length,2);});
test('lost group preview stays read-only and offers no commit',async()=>{const h=harness({post:()=>Promise.reject(Error('lost'))});await h.form();await h.find('Preview exact group').click();assert.equal(h.posts.length,1);assert(!h.find('Confirm reviewed group create'));assert(!h.ids.error.textContent.includes('may have committed'));});
test('stopped binding and proposal routes expose no authority controls',async()=>{const h=harness({servicePhase:'bindings'});await tick();h.rows[0].local_work_stopped=true;await h.view('garden/alice/inbox');assert(!h.find('Review binding for alice'));assert.match(h.ids.content.textContent,/Read-only task history/);assert(h.find('Close only this task'));});
test('stopped authorized review permits recovery and unused withdrawal only',async()=>{const h=harness({state:'authorized'});await tick();h.rows[0].local_work_stopped=true;h.card.can_withdraw=true;await h.view('garden/alice/request/'+h.card.request_id);assert(!h.find('Submit approved request'));assert(h.find('Check committed approval'));assert(h.find('Withdraw unused authorization'));await h.find('Withdraw unused authorization').click();await h.confirm('WITHDRAW alice');assert.equal(h.posts[0].request.action,'withdraw_unused');});
test('malformed group read fails visibly without review controls',async()=>{const h=harness({groups:{not:'an array'}});await tick();await h.view('relationships');assert.match(h.ids.error.textContent,/scope metadata mismatch/);assert(!h.find('Preview exact group'));assert.equal(h.posts.length,0);});
test('unknown context in group read is not displayed',async()=>{const g=group();g.members[0].context='unrelated';const h=harness({groups:[g]});await tick();await h.view('relationships/group-fictional');assert.match(h.ids.error.textContent,/Unknown exact task context/);assert(!h.ids.content.textContent.includes('unrelated'));assert(!h.find('Review stop further group work'));});
test('failed group read surfaces error rather than unhandled rejection',async()=>{const h=harness();await tick();h.context.fetch=async()=>{throw Error('fixture read failure');};await h.view('relationships');assert.match(h.ids.error.textContent,/fixture read failure/);assert.equal(h.posts.length,0);});
(async()=>{let failed=0;for(const[n,f]of tests){try{await f();console.log('PASS '+n);}catch(e){failed++;console.error('FAIL '+n+'\n'+e.stack);}}console.log(`${tests.length-failed}/${tests.length} relationship DOM-model checks passed (not browser tests).`);if(failed)process.exitCode=1;})();
